import type { Project } from '../project'
import { servicenowFrontEndPlugins, uiPageSourceManifest, rollup, glob } from '@servicenow/isomorphic-rollup'
import { path, FileSystem } from '@servicenow/sdk-build-core'
import { createSandboxedRegisterExplicitId } from './register-explicit-id'

export async function defaultUiBuild({ project }: { project: Project }): Promise<void> {
    const fs = project.getFileSystem()
    const config = project.getConfig()
    const logger = project.getLogger()
    const rootDir = project.getRootDir()
    const registerExplicitId = createSandboxedRegisterExplicitId(project)
    const clientDir = path.join(rootDir, config.clientDir)

    if (!FileSystem.existsSync(fs, clientDir)) {
        logger.debug(`No client files in ${clientDir} found, skipping UI build.`)
        return
    }

    const htmlFilePattern = path.join(clientDir, '**', '*.html')
    const htmlFiles = await glob(htmlFilePattern, { fs })
    if (!htmlFiles.length) {
        logger.warn(`No HTML files found in ${clientDir}, skipping UI build.`)
        return
    }

    const staticContentDir = path.join(rootDir, config.staticContentDir)
    fs.rmSync(staticContentDir, { recursive: true, force: true })

    const frontEndPlugins = await servicenowFrontEndPlugins({
        scope: config.scope,
        rootDir: clientDir,
        registerExplicitId: registerExplicitId as (
            table: string,
            key: string | number,
            guidOverride?: string | undefined
        ) => string,
    })

    const rollupBundle = await rollup({
        fs,
        input: htmlFilePattern,
        plugins: [...frontEndPlugins, uiPageSourceManifest({ rootDir, clientDir })],
    })
    const rollupOutput = await rollupBundle.write({
        dir: staticContentDir,
        sourcemap: true,
    })
    rollupOutput.output.forEach((file) => {
        if (file.type === 'asset') {
            logger.info(`Bundled asset: ${file.fileName} (${file.source.length} bytes)`)
        } else if (file.type === 'chunk') {
            logger.info(`Bundled chunk: ${file.fileName} (${file.code.length} bytes)`)
        }
    })
}
